import re

def parse_pair(txt):
 m=re.search(r'Demo pair \d+ input \(\d+x\d+\):\n(.*?)\nDemo pair \d+ output \(\d+x\d+\):\n(.*?)(?:\n\nSame instance|$)',txt,re.S)
 if not m: raise ValueError('no pair')
 parse=lambda s:[[int(v) for v in line.split()] for line in s.strip().splitlines()]
 return parse(m.group(1)),parse(m.group(2))
